        assert.equal(plan.runtimeRevision, '4bf5e9b3b7f2f06fbe24f50ff9457efb70a7b1a7');
        assert.equal(plan.candidate.tree, 'e87e64d0e14584c2a569d06bae8e7c602c5ed105');
