function roleOrder(repetition, phase) {
  return phase === 'diagnostics'
    ? ['candidate']
    : repetition === 2
      ? ['candidate', 'baseline']
      : ['baseline', 'candidate'];
}
export function validateRelease(release, phase, selected = null) {
